  const names = ['Alice Johnson', 'Boris Petrov', 'Carol Nguyen'];
  assert.deepStrictEqual(filterNames(names, 'johnson'), ['Alice Johnson']);
});

test('filterNames with empty or whitespace query returns all names', () => {
